package myfirstmodule.learning; final class AssessmentBank { static final String RAW="[{\"id\":\"baseline:ANALOG_ADC:0:v2\",\"form\":\"baseline\",\"system\":\"ANALOG_ADC\",\"tier\":\"Foundation\",\"concept\":\"adc_resolution\",\"prompt\":\"An ideal ADC converts which quantity into a digital code?\",\"options\":[\"The input current without a load model\",\"The absolute voltage independently of Vref\",\"An analog input voltage relative to a reference\"],\"answer\":2,\"explanation\":\"An ADC encodes an analog voltage within its configured reference range.\"},{\"id\":\"baseline:ANALOG_ADC:1:v2\",\"form\":\"baseline\",\"system\":\"ANALOG_ADC\",\"tier\":\"Applied\",\"concept\":\"adc_resolution\",\"prompt\":\"For a 10-bit ideal ADC at 3.3 V reference, the nominal step is approximately…\",\"options\":[\"3.22 mV\",\"0.322 mV\",\"3.3 mV multiplied by 1024\"],\"answer\":0,\"explanation\":\"3.3 V / 1024 is approximately 0.00322 V per nominal step.\"},{\"id\":\"baseline:ANALOG_ADC:2:v2\",\"form\":\"baseline\",\"system\":\"ANALOG_ADC\",\"tier\":\"Evidence\",\"concept\":\"adc_reference\",\"prompt\":\"Two ADCs show the same high code. What best tests whether a reference error explains it?\",\"options\":[\"Average the same high code for longer\",\"Compare measured input and measured Vref with the configured values\",\"Compare only the configured bit depths\"],\"answer\":1,\"explanation\":\"The input-to-reference ratio and configuration must be checked before attributing the code to damage.\"},{\"id\":\"practice:ANALOG_ADC:0:v2\",\"form\":\"practice\",\"system\":\"ANALOG_ADC\",\"tier\":\"Foundation\",\"concept\":\"adc_reference\",\"prompt\":\"Which change increases an ideal ADC code if other settings stay fixed?\",\"options\":[\"Lowering the input\",\"Raising the input within range\",\"Raising Vref while keeping input fixed\"],\"answer\":1,\"explanation\":\"The ideal unsaturated code increases with input at fixed reference.\"},{\"id\":\"practice:ANALOG_ADC:1:v2\",\"form\":\"practice\",\"system\":\"ANALOG_ADC\",\"tier\":\"Applied\",\"concept\":\"adc_resolution\",\"prompt\":\"At 2.048 V reference and 12 bits, the nominal step is…\",\"options\":[\"0.125 mV\",\"2 mV\",\"0.5 mV\"],\"answer\":2,\"explanation\":\"2.048 / 4096 = 0.0005 V.\"},{\"id\":\"practice:ANALOG_ADC:2:v2\",\"form\":\"practice\",\"system\":\"ANALOG_ADC\",\"tier\":\"Evidence\",\"concept\":\"adc_excitation\",\"prompt\":\"An ADC trace is flat during a constant-input test. What is needed before concluding that it is stuck?\",\"options\":[\"A controlled input change spanning several ADC steps, with corresponding readings\",\"More samples at the same constant input only\",\"A new reference setting without recording the input\"],\"answer\":0,\"explanation\":\"A constant input should give a nearly constant code. Change the input by several steps and compare the measured response before inferring a stuck converter.\"},{\"id\":\"baseline:DIGITAL_INPUT:0:v2\",\"form\":\"baseline\",\"system\":\"DIGITAL_INPUT\",\"tier\":\"Foundation\",\"concept\":\"button_polarity\",\"prompt\":\"What establishes the released state of an active-low button input?\",\"options\":[\"A suitable pull-up to the logic supply\",\"A series resistor with the input otherwise floating\",\"A software variable initialized to HIGH\"],\"answer\":0,\"explanation\":\"The pull-up defines HIGH when the switch is open.\"},{\"id\":\"baseline:DIGITAL_INPUT:1:v2\",\"form\":\"baseline\",\"system\":\"DIGITAL_INPUT\",\"tier\":\"Applied\",\"concept\":\"input_bias\",\"prompt\":\"A device specifies LOW below 0.8 V and HIGH above 2.0 V. A 1.4 V input is…\",\"options\":[\"Guaranteed LOW\",\"In the undefined region\",\"Guaranteed HIGH\"],\"answer\":1,\"explanation\":\"A voltage between the specified thresholds has no guaranteed logic interpretation.\"},{\"id\":\"baseline:DIGITAL_INPUT:2:v2\",\"form\":\"baseline\",\"system\":\"DIGITAL_INPUT\",\"tier\":\"Evidence\",\"concept\":\"button_debounce\",\"prompt\":\"Rapid edges follow one mechanical press. Which comparison tests contact bounce?\",\"options\":[\"Increase supply voltage without recording the waveform\",\"Count every edge as another intentional press\",\"Compare raw edges and a stable debounced event at the same press\"],\"answer\":2,\"explanation\":\"A controlled raw-versus-debounced comparison distinguishes contact transitions from intended events.\"},{\"id\":\"practice:DIGITAL_INPUT:0:v2\",\"form\":\"practice\",\"system\":\"DIGITAL_INPUT\",\"tier\":\"Foundation\",\"concept\":\"button_polarity\",\"prompt\":\"An unconnected CMOS input with no bias resistor is…\",\"options\":[\"Always LOW\",\"Always HIGH\",\"Not guaranteed to have a stable logic level\"],\"answer\":2,\"explanation\":\"Floating input levels depend on leakage, coupling and device conditions.\"},{\"id\":\"practice:DIGITAL_INPUT:1:v2\",\"form\":\"practice\",\"system\":\"DIGITAL_INPUT\",\"tier\":\"Applied\",\"concept\":\"input_bias\",\"prompt\":\"For LOW below 0.9 V and HIGH above 2.1 V, which reading is guaranteed HIGH?\",\"options\":[\"2.8 V\",\"1.5 V\",\"0.4 V\"],\"answer\":0,\"explanation\":\"2.8 V exceeds the HIGH threshold, provided the supply and input limits are respected.\"},{\"id\":\"practice:DIGITAL_INPUT:2:v2\",\"form\":\"practice\",\"system\":\"DIGITAL_INPUT\",\"tier\":\"Evidence\",\"concept\":\"button_debounce\",\"prompt\":\"A button sometimes reads LOW when released. What should be compared first?\",\"options\":[\"The configured input mode without checking the pin voltage\",\"Input voltage, bias configuration and switch continuity\",\"The number of LOW results without voltage or wiring checks\"],\"answer\":1,\"explanation\":\"Voltage and bias/continuity evidence can distinguish a weak bias, wiring and configuration.\"},{\"id\":\"baseline:LED_GPIO:0:v2\",\"form\":\"baseline\",\"system\":\"LED_GPIO\",\"tier\":\"Foundation\",\"concept\":\"led_resistor\",\"prompt\":\"What must a basic GPIO-driven LED circuit control?\",\"options\":[\"Only the supply voltage, regardless of load\",\"Forward current and polarity\",\"Only the commanded HIGH/LOW state\"],\"answer\":1,\"explanation\":\"LED polarity and safe current are essential; a suitable resistor or driver limits current.\"},{\"id\":\"baseline:LED_GPIO:1:v2\",\"form\":\"baseline\",\"system\":\"LED_GPIO\",\"tier\":\"Applied\",\"concept\":\"led_units\",\"prompt\":\"With 5 V supply, 2 V LED drop and 1 kohm series resistance, ideal current is…\",\"options\":[\"2 mA\",\"5 mA\",\"3 mA\"],\"answer\":2,\"explanation\":\"(5 - 2) / 1000 A = 3 mA.\"},{\"id\":\"baseline:LED_GPIO:2:v2\",\"form\":\"baseline\",\"system\":\"LED_GPIO\",\"tier\":\"Evidence\",\"concept\":\"led_evidence\",\"prompt\":\"The LED is dark despite a HIGH command. Which evidence is most useful next?\",\"options\":[\"Actual output voltage and LED current/polarity\",\"The commanded state without measuring the output\",\"The unloaded supply voltage alone\"],\"answer\":0,\"explanation\":\"A command is not measured drive; load, wiring and polarity remain competing causes.\"},{\"id\":\"practice:LED_GPIO:0:v2\",\"form\":\"practice\",\"system\":\"LED_GPIO\",\"tier\":\"Foundation\",\"concept\":\"led_resistor\",\"prompt\":\"Why check a GPIO current rating before selecting an LED load?\",\"options\":[\"The output cannot safely supply arbitrary current\",\"The voltage rating alone guarantees any LED current\",\"A HIGH output is an ideal unlimited current source\"],\"answer\":0,\"explanation\":\"Use the specified per-pin and device limits; an external driver may be required.\"},{\"id\":\"practice:LED_GPIO:1:v2\",\"form\":\"practice\",\"system\":\"LED_GPIO\",\"tier\":\"Applied\",\"concept\":\"led_units\",\"prompt\":\"A 3.3 V supply, 2.1 V LED and 600 ohms give nominal current…\",\"options\":[\"5.5 mA\",\"2 mA\",\"3.5 mA\"],\"answer\":1,\"explanation\":\"1.2 / 600 A = 0.002 A = 2 mA.\"},{\"id\":\"practice:LED_GPIO:2:v2\",\"form\":\"practice\",\"system\":\"LED_GPIO\",\"tier\":\"Evidence\",\"concept\":\"led_evidence\",\"prompt\":\"Current stops increasing at higher drive levels. What can be concluded first?\",\"options\":[\"The LED must be the unique failed component\",\"The commanded HIGH value proves that the supply did not sag\",\"The simple linear model may not explain the load; compare drive and load evidence\"],\"answer\":2,\"explanation\":\"Nonlinearity or limiting is model-mismatch evidence, not a unique damaged-component label.\"},{\"id\":\"baseline:I2C_SENSOR:0:v2\",\"form\":\"baseline\",\"system\":\"I2C_SENSOR\",\"tier\":\"Foundation\",\"concept\":\"i2c_pullup\",\"prompt\":\"On a usual open-drain I2C line, what creates a HIGH after release?\",\"options\":[\"Both devices actively driving HIGH throughout each bit\",\"The input threshold generating a HIGH voltage\",\"The pull-up network\"],\"answer\":2,\"explanation\":\"The released bus rises through its pull-up network.\"},{\"id\":\"baseline:I2C_SENSOR:1:v2\",\"form\":\"baseline\",\"system\":\"I2C_SENSOR\",\"tier\":\"Applied\",\"concept\":\"i2c_rc\",\"prompt\":\"If pull-up resistance doubles and capacitance stays fixed, the simple RC rise time…\",\"options\":[\"Approximately doubles\",\"Stays constant because clock frequency is unchanged\",\"Approximately halves\"],\"answer\":0,\"explanation\":\"The time constant is R times C in this simplified model.\"},{\"id\":\"baseline:I2C_SENSOR:2:v2\",\"form\":\"baseline\",\"system\":\"I2C_SENSOR\",\"tier\":\"Evidence\",\"concept\":\"i2c_rc\",\"prompt\":\"Can one slow rising edge identify resistance and capacitance separately?\",\"options\":[\"Yes; the ACK bit determines both R and C\",\"No; an independent value or another informative experiment is needed\",\"Yes; the rise-time measurement uniquely gives both R and C\"],\"answer\":1,\"explanation\":\"Many R,C pairs have the same product. Independent resistance readback can remove this ambiguity.\"},{\"id\":\"practice:I2C_SENSOR:0:v2\",\"form\":\"practice\",\"system\":\"I2C_SENSOR\",\"tier\":\"Foundation\",\"concept\":\"i2c_ack\",\"prompt\":\"An ACK tells you that…\",\"options\":[\"All electrical timing limits have been verified\",\"The relevant byte or transfer stage was acknowledged\",\"The sensor value has been independently calibrated\"],\"answer\":1,\"explanation\":\"ACK is transaction evidence, not proof of accuracy or a specific resistor value.\"},{\"id\":\"practice:I2C_SENSOR:1:v2\",\"form\":\"practice\",\"system\":\"I2C_SENSOR\",\"tier\":\"Applied\",\"concept\":\"i2c_rc\",\"prompt\":\"Resistance halves while capacitance doubles. In the simple RC model, rise time…\",\"options\":[\"Doubles with the capacitance\",\"Halves with the resistance\",\"Stays approximately the same\"],\"answer\":2,\"explanation\":\"The R times C product stays constant.\"},{\"id\":\"practice:I2C_SENSOR:2:v2\",\"form\":\"practice\",\"system\":\"I2C_SENSOR\",\"tier\":\"Evidence\",\"concept\":\"i2c_ack\",\"prompt\":\"A transaction has no ACK. Which next observation separates more plausible causes?\",\"options\":[\"Check device supply and configured address with wiring evidence\",\"Replace the sensor without checking its address\",\"Increase clock speed before checking power or wiring\"],\"answer\":0,\"explanation\":\"Supply, address and wiring checks distinguish alternatives; no ACK alone cannot.\"},{\"id\":\"baseline:UART_DEVICE:0:v2\",\"form\":\"baseline\",\"system\":\"UART_DEVICE\",\"tier\":\"Foundation\",\"concept\":\"uart_format\",\"prompt\":\"For a basic UART link, which pair must be connected with compatible logic levels?\",\"options\":[\"Transmitter TX to receiver RX, with an appropriate common reference\",\"TX to TX and RX to RX for an ordinary two-device link\",\"TX to RX without a compatible voltage reference\"],\"answer\":0,\"explanation\":\"The receiver observes the other device's transmit line relative to a compatible reference.\"},{\"id\":\"baseline:UART_DEVICE:1:v2\",\"form\":\"baseline\",\"system\":\"UART_DEVICE\",\"tier\":\"Applied\",\"concept\":\"uart_period\",\"prompt\":\"At 19200 bit/s, the nominal bit duration is about…\",\"options\":[\"520 microseconds\",\"52 microseconds\",\"5.2 microseconds\"],\"answer\":1,\"explanation\":\"1 / 19200 seconds is about 52.1 microseconds.\"},{\"id\":\"baseline:UART_DEVICE:2:v2\",\"form\":\"baseline\",\"system\":\"UART_DEVICE\",\"tier\":\"Evidence\",\"concept\":\"uart_payload\",\"prompt\":\"Clean edges but corrupted characters require which evidence next?\",\"options\":[\"Only the nominal baud setting at one end\",\"Only the edge amplitude, ignoring frame and payload\",\"Measured bit timing, frame settings and expected payload\"],\"answer\":2,\"explanation\":\"Baud, framing/parity, levels and payload expectations can all matter.\"},{\"id\":\"practice:UART_DEVICE:0:v2\",\"form\":\"practice\",\"system\":\"UART_DEVICE\",\"tier\":\"Foundation\",\"concept\":\"uart_format\",\"prompt\":\"UART parity settings should be…\",\"options\":[\"Enabled only at the transmitter\",\"Different at each end to detect more errors\",\"Compatible at transmitter and receiver\"],\"answer\":2,\"explanation\":\"A receiver must use a compatible frame format.\"},{\"id\":\"practice:UART_DEVICE:1:v2\",\"form\":\"practice\",\"system\":\"UART_DEVICE\",\"tier\":\"Applied\",\"concept\":\"uart_period\",\"prompt\":\"A 10-bit UART frame at 10000 bit/s lasts nominally…\",\"options\":[\"1 ms\",\"10 ms\",\"0.1 ms\"],\"answer\":0,\"explanation\":\"10 / 10000 seconds = 0.001 seconds.\"},{\"id\":\"practice:UART_DEVICE:2:v2\",\"form\":\"practice\",\"system\":\"UART_DEVICE\",\"tier\":\"Evidence\",\"concept\":\"uart_payload\",\"prompt\":\"A good frame time with an unexpected byte proves…\",\"options\":[\"An unexpected byte uniquely identifies transmitter damage\",\"Timing alone is insufficient; compare payload, framing and wiring\",\"A correct frame duration guarantees the intended byte\"],\"answer\":1,\"explanation\":\"Frame duration is one observable; it does not independently validate the intended data.\"},{\"id\":\"baseline:PWM_MOTOR_SERVO:0:v2\",\"form\":\"baseline\",\"system\":\"PWM_MOTOR_SERVO\",\"tier\":\"Foundation\",\"concept\":\"pwm_timing\",\"prompt\":\"PWM duty ratio describes…\",\"options\":[\"The number of pulses per second\",\"The fraction of each period spent HIGH\",\"The fraction of time the motor is known to rotate\"],\"answer\":1,\"explanation\":\"Duty is HIGH time divided by period.\"},{\"id\":\"baseline:PWM_MOTOR_SERVO:1:v2\",\"form\":\"baseline\",\"system\":\"PWM_MOTOR_SERVO\",\"tier\":\"Applied\",\"concept\":\"pwm_timing\",\"prompt\":\"At 2 kHz with 50% duty, nominal HIGH time is…\",\"options\":[\"1 ms\",\"0.5 ms\",\"0.25 ms\"],\"answer\":2,\"explanation\":\"The period is 0.5 ms; half is 0.25 ms.\"},{\"id\":\"baseline:PWM_MOTOR_SERVO:2:v2\",\"form\":\"baseline\",\"system\":\"PWM_MOTOR_SERVO\",\"tier\":\"Evidence\",\"concept\":\"pwm_load\",\"prompt\":\"A correct PWM command does not show motor motion. What is needed?\",\"options\":[\"An informative load-response observation or an explicitly stated load model\",\"The duty command alone to infer the actual speed\",\"Only the unloaded GPIO voltage to infer shaft motion\"],\"answer\":0,\"explanation\":\"Drive timing does not directly measure speed, torque or position.\"},{\"id\":\"practice:PWM_MOTOR_SERVO:0:v2\",\"form\":\"practice\",\"system\":\"PWM_MOTOR_SERVO\",\"tier\":\"Foundation\",\"concept\":\"pwm_timing\",\"prompt\":\"A 0% ideal PWM duty means…\",\"options\":[\"The drive stays LOW\",\"The output stays at half the supply\",\"The drive stays HIGH\"],\"answer\":0,\"explanation\":\"At 0% duty the ideal signal has no HIGH interval.\"},{\"id\":\"practice:PWM_MOTOR_SERVO:1:v2\",\"form\":\"practice\",\"system\":\"PWM_MOTOR_SERVO\",\"tier\":\"Applied\",\"concept\":\"pwm_timing\",\"prompt\":\"For 500 Hz and 20% duty, nominal HIGH time is…\",\"options\":[\"2 ms\",\"0.4 ms\",\"1.6 ms\"],\"answer\":1,\"explanation\":\"The period is 2 ms; 20% is 0.4 ms.\"},{\"id\":\"practice:PWM_MOTOR_SERVO:2:v2\",\"form\":\"practice\",\"system\":\"PWM_MOTOR_SERVO\",\"tier\":\"Evidence\",\"concept\":\"pwm_control\",\"prompt\":\"Two motor captures differ in duty, voltage and duration. What makes a gain comparison better?\",\"options\":[\"Compare only the maximum value from each short capture\",\"Set all fitted delays to zero before comparing gain\",\"Hold other conditions fixed and capture enough settled response\"],\"answer\":2,\"explanation\":\"Coupled changes and short windows confound gain, delay and time-constant estimates.\"}]"; }
